	void reorderedRawBatchesFilterBeforeTheyCanEnterAReplayCache(int maxRows) throws Exception {
		NativeLmdbQuerySource source = rawScanSource();
		RowState row = unboundRow(source);
		PatternPlan pattern = rangedPattern().withOrder(StatementOrder.S, "spoc");
		try (PatternCursor cursor = pattern.openRawUnbinding(row, 0, null)) {
			long[] buffer = new long[16];
			assertThat(cursor.fill(buffer, maxRows)).isEqualTo(1);
			assertThat(Arrays.copyOf(buffer, 4)).containsExactly(11, 7, 10, 4);
			assertThat(cursor.fill(buffer, maxRows)).isZero();
		}
	}

	private NativeLmdbQuerySource rawScanSource() throws Exception {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		when(source.statements(any(StatementOrder.class), anyLong(), anyLong(), anyLong(), anyLong(), any()))
				.thenAnswer(invocation -> new RecordIterator() {
					final long[][] rows = { { 11, 7, 30, 4 }, { 11, 7, 10, 4 } };
					int position;

					@Override
					public long[] next() {
						return position < rows.length ? rows[position++] : null;
					}

					@Override
					public void close() {
						position = rows.length;
					}
				});
		return source;
	}

	private RowState unboundRow(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "o", 1), null);
		layout.freeze(List.of("s", "o"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		return row;
	}

