			assertThat(graph(repository, construct, true)).isEqualTo(expected);
			String distinct = PREFIX
					+ "SELECT DISTINCT ?s ?n WHERE { GRAPH c:graph { ?s c:number ?n FILTER(?n < 3) } }";
			List<BindingSet> expectedRows = rows(repository, distinct, false);
			assertThat(expectedRows).hasSize(90);
			assertThat(rows(repository, distinct, true)).containsExactlyInAnyOrderElementsOf(expectedRows);
